    // 线程数据数组
    std::vector<ThreadData> thread_data(NUM_THREADS);
    std::vector<std::thread> threads;
    threads.reserve(NUM_THREADS);

    static std::atomic<uint64_t> iter{0};

    do {
        // 1. 为每个线程准备随机数据
        for (int i = 0; i < NUM_THREADS; ++i) {
            thread_data[i].src.resize(BLOCK_SIZE);
