/**
 * @copyright
 * SPDX-License-Identifier: Apache-2.0
 *
 * @test @b vmovnt3
 * @parblock
 * Simple test for vmovnt instructions - vmovntdqa (ARM64 NEON version)
 *
 * This test simulates non-temporal load and prefetch into cache using NEON
 * loads and software prefetch. It validates that data loaded from memory
 * is correctly prefetched and stored back with consistency.
 * Input data are random floats in [-1, 1].
 * @endparblock
 */

#include <sandstone.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <random>
#ifdef __aarch64__
#include <arm_neon.h>
#endif

// ============================================================================
// 测试配置
// ============================================================================

static constexpr size_t VECTOR_SIZE = 4;      // float32x4_t 含 4 个元素
static constexpr size_t NUM_VECTORS = 4;      // 总共 16 个 float（128 位 × 4 = 512 位）
static constexpr size_t TOTAL_FLOATS = NUM_VECTORS * VECTOR_SIZE;  // 16

// ============================================================================
// 辅助函数：打印浮点向量（带颜色）
// ============================================================================

static void print_vector(const char* label, const float* v, size_t len) {
    fprintf(stderr, "%s: [", label);
    for (size_t i = 0; i < len; ++i) {
        fprintf(stderr, " %.4f", v[i]);
        if (i < len - 1) fprintf(stderr, ",");
    }
    fprintf(stderr, " ]");
}

static void print_colored_result(const char* test_name, bool passed,
                                 const float* input, const float* output,
                                 size_t len) {
    const char *color = passed ? "\033[32m" : "\033[31m";
    const char *result_str = passed ? "PASS" : "FAIL";

    fprintf(stderr, "%s: %s%s\033[0m\n", test_name, color, result_str);
    print_vector("  input", input, len);
    fprintf(stderr, "\n");
    print_vector("  output", output, len);
    fprintf(stderr, "\n");
    fflush(stderr);
}

// ============================================================================
// 测试生命周期函数
// ============================================================================

static int vmovnt3_init(struct test *test) {
#ifndef __aarch64__
    (void)test;
    log_skip(CpuNotSupportedSkipCategory,
             "to be implemented (placeholder): ARM NEON required for this memory test");
    return EXIT_SKIP;
#else
    (void)test;
    return EXIT_SUCCESS;
#endif
}

static int vmovnt3_run(struct test *test, int cpu) {
    (void)cpu;
#ifdef __aarch64__
    // 线程局部数据，对齐到 16 字节（NEON 加载/存储对齐要求）
    alignas(16) float src[TOTAL_FLOATS];
    alignas(16) float store_buf[TOTAL_FLOATS];
    alignas(16) float reload_buf[TOTAL_FLOATS];

    // 每个线程独立随机数生成器
    std::mt19937 rng(std::random_device{}());
    std::uniform_real_distribution<float> dist(-1.0f, 1.0f);

    do {
        // ---------- 1. 生成随机浮点数 ----------
        for (size_t i = 0; i < TOTAL_FLOATS; ++i) {
            src[i] = dist(rng);
        }

        // ---------- 2. 模拟非临时加载 + 预取 ----------
        // 将 src 拆分为 4 个 NEON 向量并加载
        float32x4_t v0 = vld1q_f32(src);
        float32x4_t v1 = vld1q_f32(src + 4);
        float32x4_t v2 = vld1q_f32(src + 8);
        float32x4_t v3 = vld1q_f32(src + 12);

        // 软件预取：提示 CPU 预取数据到缓存（模拟 vmovntdqa 的预取效果）
        // 这里对 src 的起始地址进行预取，实际应用中预取指令通常在加载前使用。
        __builtin_prefetch(src, 0, 3);  // 读预取，高局部性

        // 为了模拟 "非临时" 特性，我们可以添加内存屏障确保顺序，但此处重点在于数据一致性

        // ---------- 3. 存储向量到 store_buf ----------
        vst1q_f32(store_buf, v0);
        vst1q_f32(store_buf + 4, v1);
        vst1q_f32(store_buf + 8, v2);
        vst1q_f32(store_buf + 12, v3);

        // 内存屏障，确保存储完成（模拟非临时存储的序列化效果）
        __sync_synchronize();

        // ---------- 4. 从 store_buf 重新加载 ----------
        float32x4_t reload0 = vld1q_f32(store_buf);
        float32x4_t reload1 = vld1q_f32(store_buf + 4);
        float32x4_t reload2 = vld1q_f32(store_buf + 8);
        float32x4_t reload3 = vld1q_f32(store_buf + 12);
        vst1q_f32(reload_buf, reload0);
        vst1q_f32(reload_buf + 4, reload1);
        vst1q_f32(reload_buf + 8, reload2);
        vst1q_f32(reload_buf + 12, reload3);

        // ---------- 5. 一致性测试：比较原始数据与重新加载的数据 ----------
        bool data_ok = (memcmp(src, reload_buf, sizeof(src)) == 0);

        // 存储一致性测试：比较存储缓冲区与重新加载的数据（应完全一致）
        bool consistent = (memcmp(store_buf, reload_buf, sizeof(store_buf)) == 0);

        bool passed = data_ok && consistent;

        // ---------- 6. 输出结果 ----------
        // 这里我们将 reload_buf 视为 "输出"（即从内存读取回来的数据）
        print_colored_result("vmovnt3", passed, src, reload_buf, TOTAL_FLOATS);

        if (!passed) {
            report_fail_msg("vmovnt3: data mismatch or consistency failure");
            return EXIT_FAILURE;
        }

    } while (test_time_condition(test));

    return EXIT_SUCCESS;
#else
    (void)test;
    log_skip(CpuNotSupportedSkipCategory,
             "to be implemented (placeholder): ARM NEON required for this memory test");
    return EXIT_SKIP;
#endif
}

static int vmovnt3_finish(struct test *test) {
    (void)test;
    return EXIT_SUCCESS;
}

// ============================================================================
// 测试注册
// ============================================================================

DECLARE_TEST(vmovnt3,
             "Simple test for vmovnt instructions - vmovntdqa (ARM64 NEON)")
    .groups = DECLARE_TEST_GROUPS(&group_math),
    .test_init = vmovnt3_init,
    .test_run = vmovnt3_run,
    .test_cleanup = vmovnt3_finish,
    .quality_level = TEST_QUALITY_PROD,
END_DECLARE_TEST

/*
 *  memcpy_rewr.cpp - producer/consumer memcpy coherence stress test for
 *  SDCShield (ARM64).
 *
 *  Origin: a standalone GlusterFS-IOT-scheduler-derived MPSC stress tool
 *  (memcpy_rewr.c) that spawns pinned producer/consumer pthreads, routes
 *  requests through a 4-priority linked-list queue, and - crucially -
 *  checks that memcpy of the per-thread mem_info_s buffers yields byte-
 *  identical copies across b1..b5. A mismatch that does *not* crash is
 *  exactly the silent-data-corruption (SDC) SDCShield exists to catch.
 *
 *  Port to SDCShield
 *  ------------------
 *  - The standalone main()+pthread_create is replaced by the framework's
 *    forked-child + per-CPU worker-thread model. Each test_run(test,cpu)
 *    thread IS one pinned worker (the framework already pins it to
 *    device_info[cpu].cpu_number, equivalent to the original
 *    pthread_setaffinity_np). Roles (producer vs consumer) are assigned
 *    from CPU topology via device_info[cpu].numa_id/die_id/core_id, per
 *    the selected strategy (see memcpy_rewr_strategies.conf).
 *  - The MPSC queue, the ARM64 arch-timer cycle source, the sync
 *    primitives (__yawn/__wake/__yield), the mem_info_s layout, and the
 *    b1..b5 memcpy+memcmp SDC check are preserved verbatim.
 *  - Strategy selection is handled by the reusable strategy_config
 *    framework (SANDSTONE_STRATEGY_INDEX cycles strategies round-robin
 *    across repeated invocations; SANDSTONE_STRATEGY_CONF overrides the
 *    config path). When no config file is present (default path missing
 *    or SANDSTONE_STRATEGY_CONF dangling), the test degrades to the
 *    original tool's default mode instead of skipping: first-N-producers
 *    roles (N = max(1, threads/12)) and a MemAvailable-adaptive block_size
 *    clamped to [64 KiB, c_size] — see default_block_size() in the
 *    implementation.
 *
 *  ARM64-only: the arch-timer inline asm (mrs cntvct_el0 / cntfrq_el0) has
 *  no x86 equivalent and the x86-64 paths must stay untouched, so this
 *  test is built and registered only on aarch64 (see meson.build guard).
 *
 *  SPDX-License-Identifier: Apache-2.0
 */
#include <sandstone.h>

#ifdef __aarch64__

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <atomic>
#include <algorithm>
#include <vector>

#include <pthread.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>   /* access() for conf-existence probe */
#include <cerrno>     /* ENOENT/ENOTDIR discrimination     */

#include "list.h"
#include "strategy_config.h"

/* ---- original per-transfer buffer geometry (unchanged) ----
 * c_size is 2 MiB; the per-thread mem_info_s packs five 2 MiB fields (b1..b5)
 * interleaved with small tag arrays and aligned to 128 bytes. The 65536-byte
 * block_size configured in the .conf only ever touches the front of each
 * field, but the full struct is allocated so the layout - and thus the cache
 * colouring / aliasing behaviour being stressed - is identical to upstream.
 */
#define c_size (1024 * 1024 * 2)

struct mem_info_s {
    unsigned char flag;
    unsigned char b1[c_size];   // 1
    unsigned char num[7];
    unsigned char b2[c_size];   // 8
    unsigned char boy[3];
    unsigned char b3[c_size];   // 3
    unsigned char girl[4];
    unsigned char b4[c_size];   // 8
    unsigned char uncle[5];
    unsigned char b5[c_size];   // 5
} __attribute__((__aligned__(128)));

struct iatt {
    char data[128];
};

struct syncargs {
    int op_ret;
    int op_errno;
    struct iatt iatt1;
    struct iatt iatt2;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int done;
};

typedef enum {
    IOT_PRI_HI = 0,      /* low latency */
    IOT_PRI_NORMAL,      /* normal */
    IOT_PRI_LO,          /* bulk */
    IOT_PRI_LEAST,       /* least */
    IOT_PRI_MAX,
} iot_pri_t;

typedef struct {
    struct list_head clients;
    struct list_head reqs;
} iot_client_ctx_t;

enum _gf_boolean { _gf_false = 0, _gf_true = 1 };
typedef enum _gf_boolean gf_boolean_t;

struct iot_conf {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int32_t max_count;     /* configured maximum */
    int32_t curr_count;    /* actual number of threads running */
    int32_t sleep_count;
    int32_t idle_time;     /* in seconds */
    struct list_head clients[IOT_PRI_MAX];
    iot_client_ctx_t no_client[IOT_PRI_MAX];
    int32_t ac_iot_limit[IOT_PRI_MAX];
    int32_t ac_iot_count[IOT_PRI_MAX];
    int queue_sizes[IOT_PRI_MAX];
    int queue_size;
    pthread_attr_t w_attr;
    gf_boolean_t least_priority;
    void *self;                 /* upstream field named 'this'; renamed for C++ */
    size_t stack_size;
    gf_boolean_t down;
    gf_boolean_t mutex_inited;
    gf_boolean_t cond_inited;
};
typedef struct iot_conf iot_conf_t;

#define __yawn(args)                            \
    do {                                        \
        pthread_mutex_init(&args->mutex, NULL); \
        pthread_cond_init(&args->cond, NULL);   \
        args->done = 0;                         \
    } while (0)
#define __wake(args)                          \
    do {                                      \
        pthread_mutex_lock(&args->mutex);     \
        {                                     \
            args->done = 1;                   \
            pthread_cond_signal(&args->cond); \
        }                                     \
