7	#include <cstdio>
8	#ifdef __aarch64__
9	#include <arm_neon.h>          // NEON intrinsics (aarch64 only)
10	#include <sys/auxv.h>         // hardware feature detection (aarch64)
11	#endif
12	
13	static constexpr size_t CACHE_LINE_SIZE = 64;
14	
15	#ifdef __aarch64__
16	// 共享数据：128位NEON向量（4个float）对齐到缓存行
17	struct alignas(CACHE_LINE_SIZE) SharedData {
18	    float32x4_t victim_value;          // 128位NEON向量
19	    std::atomic<bool> stop;
20	    std::atomic<uint64_t> iteration_count;
21	};
22	
23	// ARM 缓存行冲刷（将指定地址的缓存行写回并无效）
24	static inline void clflush_arm(void *ptr) {
25	    // 使用内联汇编执行 DC CIVAC（数据缓存清空并无效）
26	    // 注意：需要特权级别，若在用户空间可能无效，需通过 __clear_cache 等
27	    // 这里使用 __builtin___clear_cache 作为通用替代（会清空指令缓存，但对数据也有效）
28	    __builtin___clear_cache((char*)ptr, (char*)ptr + CACHE_LINE_SIZE);
29	    // 内存屏障确保冲刷完成
30	    __sync_synchronize();
31	}
32	
33	static void aggressor_thread(SharedData *data) {
34	    while (!data->stop.load(std::memory_order_relaxed)) {
35	        clflush_arm((void*)data);
36	        std::this_thread::sleep_for(std::chrono::microseconds(1));
37	    }
38	}
39	
40	static void victim_thread(SharedData *data) {
41	    // 生成随机浮点数向量（这里用固定值递增，但可改为随机）
42	    float base = 0.0f;
