20	static int atomic_simd_256_init(struct test *test) {
21	    auto *sd = new SharedData;
22	    if (!sd) return EXIT_FAILURE;
23	    sd->data0 = vdupq_n_u8(0);
24	    sd->data1 = vdupq_n_u8(0);
25	    sd->seq.store(0, std::memory_order_relaxed);
26	    test->data = sd;
27	    return EXIT_SUCCESS;
28	}
