30	static int atomic_simd_256_run(struct test *test, int cpu) {
31	    (void)cpu;
32	    auto *sd = static_cast<SharedData*>(test->data);
33	    std::mt19937 rng(static_cast<unsigned>(time(nullptr)) + getpid());
34	    std::uniform_int_distribution<int> dist(0, 1);
35	    static std::atomic<uint64_t> iter{0};
36	
37	    do {
38	        uint64_t pattern = dist(rng);
39	        uint8x16_t val0 = pattern ? vdupq_n_u8(0xFF) : vdupq_n_u8(0);
40	        uint8x16_t val1 = val0;   // 全0或全1
41	
42	        // 写操作：分别存储两个 128 位块（对齐）
43	        sd->seq.fetch_add(1, std::memory_order_acq_rel);
44	        vst1q_u8((uint8_t*)&sd->data0, val0);
45	        vst1q_u8((uint8_t*)&sd->data1, val1);
46	        sd->seq.fetch_add(1, std::memory_order_acq_rel);
47	
48	        // 读操作：分别加载两个 128 位块
49	        uint64_t s1, s2;
50	        uint8x16_t read0, read1;
51	        do {
52	            s1 = sd->seq.load(std::memory_order_acquire);
53	            read0 = vld1q_u8((uint8_t*)&sd->data0);
54	            read1 = vld1q_u8((uint8_t*)&sd->data1);
55	            s2 = sd->seq.load(std::memory_order_acquire);
56	        } while (s1 != s2 || (s1 & 1));
57	
58	        // 验证数据完整性：检查读出的两个块是否全0或全1
59	        uint8_t bytes[32];
