1	/**
2	 * @copyright
3	 * Copyright 2026.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b lsu_store_forward_arm
7	 * @parblock
8	 * Load/Store Unit SDC stress — a coverage-weak unit (LSU 54%). The suite's
9	 * existing memory tests (memcpy_*, mem_disambiguation, mfence) move data
10	 * bulk or test ordering, but none target the LSU's most SDC-prone
11	 * micro-path: the **store buffer → load forwarding** datapath, where a
12	 * subsequent load to a just-stored address is satisfied by the store buffer
13	 * before the store retires to L1. A fault in forwarding (wrong lane merge,
14	 * wrong partial-forward, store-buffer entry corruption) silently produces a
15	 * load value that differs from what was stored — the canonical LSU SDC.
16	 *
17	 * This test exercises every forwarding case the silicon must handle:
18	 *
19	 *   1. **Same-size forward at every access width and offset**: store then
20	 *      immediately load the SAME address at widths 1/2/4/8/16 bytes and at
21	 *      offsets 0,1,2,3,7,8,12,15 — including line_end-8..line_end-1 where
22	 *      the access straddles a 64B cache-line boundary (the split-forward
23	 *      path, where the forward merges two store-buffer entries). Inline-asm
24	 *      str/ldr/stp/ldp with a "memory" clobber so the optimizer cannot
25	 *      elide the store or the load (a real forward, not a reg-reg copy).
26	 *   2. **Partial-store forwarding / store-merging**: overlapping stores of
27	 *      different widths into one cache line (store 1B at 0, 2B at 1, 4B at
28	 *      3, then load 8B at 0) — the LSU must merge the partial stores into
29	 *      the forwarded load. A merge fault corrupts the loaded bytes.
30	 *   3. **Store-after-load hazard**: a load immediately followed by a store
31	 *      to the same address (RAW then WAW), interleaved with a forward —
32	 *      stresses address-matching / hazard detection in the store buffer.
33	 *   4. **NEON 128B store + reload across the line**: a 16B stp/ldp at the
34	 *      line boundary (offset 56, 8B per line) — the 128-bit forward path.
35	 *   5. **Strided store-then-load across a full cache line**: store 8B every
36	 *      8 bytes across one 64B line, then reload each — exercises the
37	 *      multi-entry store-buffer forward under back-to-back same-line traffic.
38	 *
39	 * SDC detection: every forward is byte-exact compared against the value
40	 * stored; report_fail_msg on any mismatch. ARM64-native (inline-asm
41	 * str/ldr/strb/ldrb/strh/ldrh/stp/ldp); non-aarch64 returns a clean
42	 * EXIT_SKIP. Wired into the arm64 subdir (aarch64-only guard), so x86-64 is
43	 * untouched.
44	 *
45	 * Note: the regular str/ldr/stp/ldp class tolerates misalignment on
46	 * Kunpeng 920 (verified), so the cross-line offset probes (line_end-8..-1)
47	 * do NOT raise BUS_ADRALN — only the exclusive class and dc-civac do (see
48	 * the l2c_cross_cache_line_arm alignment note). This test deliberately
49	 * uses the regular class for the misaligned probes.
50	 * @endparblock
51	 */
52	
53	#include <sandstone.h>
54	#include <cstdint>
55	#include <cinttypes>
56	#include <cstring>
57	
58	static constexpr size_t CACHE_LINE = 64;
59	
60	// High-Hamming golden table — successive cycles toggle the data-path gates.
61	static const uint64_t GOLDEN_TABLE[] = {
62	    0x0000000000000000ULL,
63	    0xFFFFFFFFFFFFFFFFULL,
64	    0xAAAAAAAAAAAAAAAAULL,
65	    0x5555555555555555ULL,
66	    0x0F0F0F0F0F0F0F0FULL,
67	    0xF0F0F0F0F0F0F0F0ULL,
68	};
69	static constexpr size_t GOLDEN_TABLE_SIZE =
70	    sizeof(GOLDEN_TABLE) / sizeof(GOLDEN_TABLE[0]);
71	
72	#if defined(__aarch64__)
73	// Byte/halfword/word/doubleword inline-asm store+load, "memory" clobber so
74	// the compiler emits real str/ldr micro-ops and cannot elide the round-trip.
75	static inline void sf_store8(void *a, uint8_t v)
76	{ __asm__ volatile("strb %w1, [%0]" : : "r"(a), "r"((uint32_t)v) : "memory"); }
77	static inline uint8_t sf_load8(const void *a)
78	{ uint32_t r; __asm__ volatile("ldrb %w0, [%1]" : "=r"(r) : "r"(a) : "memory"); return (uint8_t)r; }
79	static inline void sf_store16(void *a, uint16_t v)
80	{ __asm__ volatile("strh %w1, [%0]" : : "r"(a), "r"((uint32_t)v) : "memory"); }
81	static inline uint16_t sf_load16(const void *a)
82	{ uint32_t r; __asm__ volatile("ldrh %w0, [%1]" : "=r"(r) : "r"(a) : "memory"); return (uint16_t)r; }
83	static inline void sf_store32(void *a, uint32_t v)
84	{ __asm__ volatile("str %w1, [%0]" : : "r"(a), "r"(v) : "memory"); }
85	static inline uint32_t sf_load32(const void *a)
86	{ uint32_t r; __asm__ volatile("ldr %w0, [%1]" : "=r"(r) : "r"(a) : "memory"); return r; }
87	static inline void sf_store64(void *a, uint64_t v)
88	{ __asm__ volatile("str %1, [%0]" : : "r"(a), "r"(v) : "memory"); }
89	static inline uint64_t sf_load64(const void *a)
90	{ uint64_t r; __asm__ volatile("ldr %0, [%1]" : "=r"(r) : "r"(a) : "memory"); return r; }
91	static inline void sf_store128(void *a, uint64_t lo, uint64_t hi)
92	{ __asm__ volatile("stp %2, %3, [%0]" : : "r"(a), "r"(0), "r"(lo), "r"(hi) : "memory"); }
93	static inline void sf_load128(const void *a, uint64_t *lo, uint64_t *hi)
94	{ __asm__ volatile("ldp %0, %1, [%2]" : "=r"(*lo), "=r"(*hi) : "r"(a) : "memory"); }
95	#else
96	static inline void sf_store8(void *a, uint8_t v) { std::memcpy(a, &v, 1); }
97	static inline uint8_t sf_load8(const void *a) { uint8_t v; std::memcpy(&v, a, 1); return v; }
98	static inline void sf_store16(void *a, uint16_t v) { std::memcpy(a, &v, 2); }
99	static inline uint16_t sf_load16(const void *a) { uint16_t v; std::memcpy(&v, a, 2); return v; }
100	static inline void sf_store32(void *a, uint32_t v) { std::memcpy(a, &v, 4); }
101	static inline uint32_t sf_load32(const void *a) { uint32_t v; std::memcpy(&v, a, 4); return v; }
102	static inline void sf_store64(void *a, uint64_t v) { std::memcpy(a, &v, 8); }
103	static inline uint64_t sf_load64(const void *a) { uint64_t v; std::memcpy(&v, a, 8); return v; }
104	static inline void sf_store128(void *a, uint64_t lo, uint64_t hi) { uint64_t p[2]={lo,hi}; std::memcpy(a,p,16); }
105	static inline void sf_load128(const void *a, uint64_t *lo, uint64_t *hi) { uint64_t p[2]; std::memcpy(p,a,16); *lo=p[0]; *hi=p[1]; }
106	#endif
107	
108	static int lsu_store_forward_arm_init(struct test *test)
109	{
110	    (void)test;
111	    return EXIT_SUCCESS;
112	}
113	
114	#ifdef __aarch64__
115	
116	static int lsu_store_forward_arm_run(struct test *test, int cpu)
117	{
118	    (void)cpu;
119	    (void)test;
120	
121	    // A 2-cache-line buffer: line0 = [0..63], line1 = [64..127]. Aligned so
122	    // line_end is exactly at offset 64. The cross-line probes use offsets
123	    // 56..63 of line0 (an access there straddles into line1).
124	    uint8_t *buf = static_cast<uint8_t *>(aligned_alloc_safe(CACHE_LINE, CACHE_LINE * 2));
125	    if (!buf) {
126	        log_skip(TestResourceIssueSkipCategory,
127	                 "lsu_store_forward_arm: alloc failed");
128	        return EXIT_SKIP;
129	    }
130	
131	    do {
132	        bool all_passed = true;
133	        static uint64_t golden_cycle = 0;
134	        uint64_t g0 = GOLDEN_TABLE[golden_cycle % GOLDEN_TABLE_SIZE];
135	        uint64_t g1 = GOLDEN_TABLE[(golden_cycle + 1) % GOLDEN_TABLE_SIZE];
136	        uint64_t g2 = GOLDEN_TABLE[(golden_cycle + 2) % GOLDEN_TABLE_SIZE];
137	        golden_cycle = (golden_cycle + 1) % GOLDEN_TABLE_SIZE;
138	
139	        // ---- (1) Same-size forward at every width, sweeping offsets that
140	        // include the line boundary (offsets 56..63 straddle line0/line1).
141	        // For each (width, offset): store the golden (low width bytes),
142	        // immediately load the same address, compare byte-exact.
143	        // Offsets: 0,1,2,3,7,8,12,15 then the boundary run 56..63.
144	        static const unsigned offsets[] = {0, 1, 2, 3, 7, 8, 12, 15,
145	                                           56, 57, 58, 59, 60, 61, 62, 63};
146	        constexpr size_t NUM_OFF = sizeof(offsets) / sizeof(offsets[0]);
147	
148	        // 1-byte forward (strb/ldrb) at every offset.
149	        for (size_t i = 0; i < NUM_OFF; ++i) {
150	            uint8_t want = (uint8_t)(g0 >> ((i % 8) * 8));
151	            sf_store8(buf + offsets[i], want);
152	            uint8_t got = sf_load8(buf + offsets[i]);
153	            if (got != want) {
154	                log_warning("lsu_store_forward_arm: 1B fwd off %u "
155	                            "got 0x%02x want 0x%02x", offsets[i], got, want);
156	                all_passed = false;
157	            }
158	        }
159	        // 2-byte forward (strh/ldrh) at offsets where 2 bytes fit (<=62)
160	        // and at the boundary (56..62 straddle).
161	        for (size_t i = 0; i < NUM_OFF; ++i) {
162	            if (offsets[i] > 62) continue; // 2B access; let boundary straddle
163	            uint16_t want = (uint16_t)(g1 >> ((i % 4) * 4));
164	            sf_store16(buf + offsets[i], want);
165	            uint16_t got = sf_load16(buf + offsets[i]);
166	            if (got != want) {
167	                log_warning("lsu_store_forward_arm: 2B fwd off %u "
168	                            "got 0x%04x want 0x%04x", offsets[i], got, want);
169	                all_passed = false;
170	            }
171	        }
172	        // 4-byte forward (str/ldr) — offsets <=60.
173	        for (size_t i = 0; i < NUM_OFF; ++i) {
174	            if (offsets[i] > 60) continue;
175	            uint32_t want = (uint32_t)(g2 ^ (uint32_t)(i * 0x11111111u));
176	            sf_store32(buf + offsets[i], want);
177	            uint32_t got = sf_load32(buf + offsets[i]);
178	            if (got != want) {
179	                log_warning("lsu_store_forward_arm: 4B fwd off %u "
180	                            "got 0x%08x want 0x%08x", offsets[i], got, want);
181	                all_passed = false;
182	            }
183	        }
184	        // 8-byte forward (str/ldr) — offsets <=56 (56 straddles line0/line1).
185	        for (size_t i = 0; i < NUM_OFF; ++i) {
186	            if (offsets[i] > 56) continue;
187	            uint64_t want = g0 ^ (i * 0x9E3779B97F4A7C15ULL);
188	            sf_store64(buf + offsets[i], want);
189	            uint64_t got = sf_load64(buf + offsets[i]);
190	            if (got != want) {
191	                log_warning("lsu_store_forward_arm: 8B fwd off %u "
192	                            "got 0x%016" PRIx64 " want 0x%016" PRIx64,
193	                            offsets[i], got, want);
194	                all_passed = false;
195	            }
196	        }
197	        // 16-byte forward (stp/ldp) — offsets <=48 (48..63 all in line0;
198	        // offset 56 straddles line0/line1 with 8B in each line).
199	        for (size_t i = 0; i < NUM_OFF; ++i) {
200	            if (offsets[i] > 56) continue;
201	            uint64_t lo = g1 ^ (i * 0x0123456789ABCDEFULL);
202	            uint64_t hi = g2 ^ (i * 0xFEDCBA9876543210ULL);
203	            sf_store128(buf + offsets[i], lo, hi);
204	            uint64_t glo, ghi;
205	            sf_load128(buf + offsets[i], &glo, &ghi);
206	            if (glo != lo || ghi != hi) {
207	                log_warning("lsu_store_forward_arm: 16B fwd off %u "
208	                            "lo=0x%016" PRIx64 "/0x%016" PRIx64 " "
209	                            "hi=0x%016" PRIx64 "/0x%016" PRIx64,
210	                            offsets[i], glo, lo, ghi, hi);
211	                all_passed = false;
212	            }
213	        }
214	
215	        // ---- (2) Partial-store forwarding / store-merging. Write
216	        // overlapping partial stores into one 8-byte slot, then load the
217	        // full 8 bytes — the LSU must merge the partial stores into the
218	        // forwarded load. Build the expected merged value in software.
219	        std::memset(buf, 0, CACHE_LINE * 2); // clean slate
220	        // Store 1B at 0, 2B at 1, 4B at 3, 1B at 7 — all into bytes 0..7.
221	        uint8_t  b0 = (uint8_t)(g0);
222	        uint16_t h1 = (uint16_t)(g1);
223	        uint32_t w3 = (uint32_t)(g2);
224	        uint8_t  b7 = (uint8_t)(g0 >> 8);
225	        sf_store8(buf + 0, b0);
226	        sf_store16(buf + 1, h1);
227	        sf_store32(buf + 3, w3);
228	        sf_store8(buf + 7, b7);
229	        // Compute the merged 8-byte expectation (little-endian).
230	        uint8_t merged[8] = {0,0,0,0,0,0,0,0};
231	        merged[0] = b0;                       // byte 0
232	        merged[1] = (uint8_t)(h1 & 0xff);     // byte 1 (low of h1)
233	        merged[2] = (uint8_t)(h1 >> 8);       // byte 2 (high of h1)
234	        merged[3] = (uint8_t)(w3 & 0xff);     // byte 3 (low of w3)
235	        merged[4] = (uint8_t)(w3 >> 8);       // byte 4
236	        merged[5] = (uint8_t)(w3 >> 16);      // byte 5
237	        merged[6] = (uint8_t)(w3 >> 24);      // byte 6
238	        merged[7] = b7;                       // byte 7 (overwrites? no, w3 was bytes 3-6, b7 is byte 7)
239	        uint64_t merged64;
240	        std::memcpy(&merged64, merged, 8);
241	        uint64_t fwd64 = sf_load64(buf + 0);
242	        if (fwd64 != merged64) {
243	            log_warning("lsu_store_forward_arm: partial-fwd merge "
244	                        "got 0x%016" PRIx64 " want 0x%016" PRIx64,
245	                        fwd64, merged64);
246	            all_passed = false;
247	        }
248	
249	        // ---- (3) Store-after-load hazard. Load the just-merged value,
250	        // then store a new golden over it, then forward-load — the LSU must
251	        // handle the RAW then WAW then RAW sequence.
252	        (void)sf_load64(buf + 0);             // RAW read of merged value
253	        uint64_t haz = g0 ^ g1;
254	        sf_store64(buf + 0, haz);
255	        uint64_t haz_rd = sf_load64(buf + 0); // forward of the new store
256	        if (haz_rd != haz) {
257	            log_warning("lsu_store_forward_arm: hazard fwd "
258	                        "got 0x%016" PRIx64 " want 0x%016" PRIx64,
259	                        haz_rd, haz);
260	            all_passed = false;
261	        }
262	
263	        // ---- (4) NEON 128B cross-line forward (offset 56: 8B in line0,
264	        // 8B in line1).
265	        sf_store128(buf + 56, g0, g1);
266	        uint64_t clo, chi;
267	        sf_load128(buf + 56, &clo, &chi);
268	        if (clo != g0 || chi != g1) {
269	            log_warning("lsu_store_forward_arm: 128B cross-line fwd "
270	                        "lo=0x%016" PRIx64 "/0x%016" PRIx64 " "
271	                        "hi=0x%016" PRIx64 "/0x%016" PRIx64,
272	                        clo, g0, chi, g1);
273	            all_passed = false;
274	        }
275	
276	        // ---- (5) Strided store-then-load across one full cache line.
277	        // Store 8B every 8 bytes across line0, then reload each — multi-
278	        // entry store-buffer forward under back-to-back same-line traffic.
279	        uint64_t stride_golden[CACHE_LINE / 8];
280	        for (size_t i = 0; i < CACHE_LINE / 8; ++i) {
281	            stride_golden[i] = GOLDEN_TABLE[i % GOLDEN_TABLE_SIZE]
282	                               ^ (i * 0x9E3779B97F4A7C15ULL);
283	            sf_store64(buf + i * 8, stride_golden[i]);
284	        }
285	        for (size_t i = 0; i < CACHE_LINE / 8; ++i) {
286	            uint64_t got = sf_load64(buf + i * 8);
287	            if (got != stride_golden[i]) {
288	                log_warning("lsu_store_forward_arm: stride fwd slot %zu "
289	                            "got 0x%016" PRIx64 " want 0x%016" PRIx64,
290	                            i, got, stride_golden[i]);
291	                all_passed = false;
292	            }
293	        }
294	
295	        if (!all_passed) {
296	            free(buf);
297	            report_fail_msg("lsu_store_forward_arm: store-buffer/load "
298	                             "forwarding SDC detected");
299	            return EXIT_FAILURE;
300	        }
301	
302	    } while (test_time_condition(test));
303	
304	    free(buf);
305	    return EXIT_SUCCESS;
306	}
307	#else
308	static int lsu_store_forward_arm_run(struct test *test, int cpu)
309	{
310	    (void)cpu;
311	    (void)test;
312	    log_skip(CpuNotSupportedSkipCategory,
313	             "to be implemented (placeholder): aarch64 LSU store-to-load "
314	             "forwarding (inline-asm str/ldr/strb/ldrb/strh/ldrh/stp/ldp) "
315	             "required");
316	    return EXIT_SKIP;
317	}
318	#endif
319	
320	static int lsu_store_forward_arm_finish(struct test *test)
321	{
322	    (void)test;
323	    return EXIT_SUCCESS;
324	}
325	
326	DECLARE_TEST(lsu_store_forward_arm,
327	             "LSU store-buffer/load-forwarding SDC stress: same-size forward "
328	             "at widths 1/2/4/8/16B and offsets including the line boundary, "
329	             "partial-store forwarding/merging, store-after-load hazard, "
330	             "128B cross-line forward, and strided same-line forward "
331	             "(ARM64 inline-asm)")
332	    .groups = DECLARE_TEST_GROUPS(&group_math),
333	    .test_init = lsu_store_forward_arm_init,
334	    .test_run = lsu_store_forward_arm_run,
335	    .test_cleanup = lsu_store_forward_arm_finish,
336	    .quality_level = TEST_QUALITY_PROD,
337	END_DECLARE_TEST
338

