50	struct SveGatherScatterData {
51	    size_t vl_d;
52	    std::vector<uint64_t> seeds_f64;   // 只读共享
53	    std::vector<uint64_t> gather_src;  // 只读共享
54	    std::vector<uint64_t> gather_idx;  // 只读共享(置换索引表)
55	    // 注意: scatter_dst / scatter_golden 是每线程每迭代的可变 scratch,不能放共享 data ——
56	    // -n>1 时框架对每个 worker 线程共享同一个 test->data,并发改写同一块 scatter 缓冲会
57	    // 相互踩踏(实测 -n 4 时上半 lane 读到 0x0:某线程的 std::fill 清掉了另一线程正在比对的
