63	static void gather_scatter_golden(const SveGatherScatterData *d, uint64_t *golden_out)
64	{
65	    for (size_t i = 0; i < d->gather_idx.size(); ++i) {
66	        double v;
67	        memcpy(&v, &d->gather_src[d->gather_idx[i]], 8);
68	        v = std::fma(v, v, 1.5);
69	        memcpy(&golden_out[d->gather_idx[i]], &v, 8);
70	    }
71	}
