            std::memcpy(&bits, &data->fvalues[i * 4 + j], sizeof(bits));
            if (bits & 0x80000000u)
                mask |= (1u << j);
        }
        data->fexpected[i] = mask;

        mask = 0;
        for (int j = 0; j < 2; j++) {
            uint64_t bits;
            std::memcpy(&bits, &data->dvalues[i * 2 + j], sizeof(bits));
